// 5 posts, each with an authorId
const POSTS = [
  { id: 1, authorId: 10 },
  { id: 2, authorId: 11 },
  { id: 3, authorId: 10 },
  { id: 4, authorId: 12 },
  { id: 5, authorId: 11 },
];
const AUTHORS = { 10: 'Ada', 11: 'Linus', 12: 'Grace' };

// The client's GraphQL request, modeled as a selection set.
const info = { selectionSet: ['id', 'author'] };
function selectionContains(info, field) {
  return info.selectionSet.includes(field);
}

// --- lazy resolver: posts first, then author per post ---
function resolveLazy(info) {
  let queries = 0;
  queries++; // SELECT * FROM posts
  const posts = POSTS.map((p) => ({ ...p }));
  if (selectionContains(info, 'author')) {
    for (const p of posts) {
      queries++; // SELECT name FROM users WHERE id = p.authorId  (one per post)
      p.author = AUTHORS[p.authorId];
    }
  }
  return { queries, rows: posts.length };
}

// --- lookahead resolver: inspect selection set, pre-join up front ---
function resolveLookahead(info) {
  let queries = 0;
  const wantsAuthor = selectionContains(info, 'author');
  // One query whether or not author is requested: JOIN added only when needed.
  queries++; // SELECT posts.*, users.name FROM posts [JOIN users ...]
  const posts = POSTS.map((p) => ({
    ...p,
    ...(wantsAuthor ? { author: AUTHORS[p.authorId] } : {}),
  }));
  return { queries, rows: posts.length, joined: wantsAuthor };
}

const lazy = resolveLazy(info);
const look = resolveLookahead(info);
console.log(
  'lazy (1+N): ' + lazy.queries + ' queries | ' +
  'lookahead (pre-join): ' + look.queries + ' query | ' +
  'saved: ' + (lazy.queries - look.queries)
);
